add_filter( 'woocommerce_package_rates', 'perfectpixel_sort_shipping_rates_by_cost', 9999 );

function perfectpixel_sort_shipping_rates_by_cost( $rates ) {
	if ( count( $rates ) < 2 ) {
		return $rates;
	}
	uasort(
		$rates,
		static function ( $a, $b ) {
			$cost_a = (float) $a->get_cost() + array_sum( (array) $a->get_taxes() );
			$cost_b = (float) $b->get_cost() + array_sum( (array) $b->get_taxes() );
			return $cost_a <=> $cost_b;
		}
	);
	return $rates;
}
